package dao;

import config.DBConnection;
import model.Reservation;
import java.sql.*;
import java.time.LocalDate;

public class ReservationDAO {
    public int createReservation(Reservation r,Connection c)throws SQLException{String s="INSERT INTO reservations (guest_id,room_id,check_in,check_out,status) VALUES (?,?,?,?, 'BOOKED')";try(PreparedStatement p=c.prepareStatement(s,Statement.RETURN_GENERATED_KEYS)){p.setInt(1,r.getGuestId());p.setInt(2,r.getRoomId());p.setDate(3,Date.valueOf(r.getCheckIn()));p.setDate(4,Date.valueOf(r.getCheckOut()));p.executeUpdate();try(ResultSet x=p.getGeneratedKeys()){return x.next()?x.getInt(1):-1;}}}
    public boolean isRoomAvailable(int roomId,LocalDate in,LocalDate out,Connection c)throws SQLException{String s="SELECT COUNT(*) FROM reservations WHERE room_id=? AND status IN ('BOOKED','CHECKED_IN') AND check_in < ? AND check_out > ?";try(PreparedStatement p=c.prepareStatement(s)){p.setInt(1,roomId);p.setDate(2,Date.valueOf(out));p.setDate(3,Date.valueOf(in));try(ResultSet r=p.executeQuery()){return r.next()&&r.getInt(1)==0;}}}
    public void viewAllReservations()throws SQLException{String s="SELECT r.reservation_id,g.guest_name,g.contact_no,rm.room_number,rm.room_type,r.check_in,r.check_out,r.status FROM reservations r JOIN guests g ON r.guest_id=g.guest_id JOIN rooms rm ON r.room_id=rm.room_id ORDER BY r.reservation_id";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s);ResultSet r=p.executeQuery()){boolean found=false;System.out.println("\n===== ALL RESERVATIONS =====");while(r.next()){found=true;System.out.printf("ID:%d | Guest:%s | Contact:%s | Room:%d | Type:%s | %s to %s | %s%n",r.getInt(1),r.getString(2),r.getString(3),r.getInt(4),r.getString(5),r.getDate(6),r.getDate(7),r.getString(8));}if(!found)System.out.println("No reservations found!");}}
    public Reservation findById(int id)throws SQLException{String s="SELECT * FROM reservations WHERE reservation_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(r.next()){Reservation x=new Reservation(r.getInt("guest_id"),r.getInt("room_id"),r.getDate("check_in").toLocalDate(),r.getDate("check_out").toLocalDate());x.setReservationId(r.getInt("reservation_id"));x.setStatus(r.getString("status"));return x;}}}return null;}
    public boolean updateReservation(int id,LocalDate in,LocalDate out)throws SQLException{String s="UPDATE reservations SET check_in=?,check_out=? WHERE reservation_id=? AND status='BOOKED'";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setDate(1,Date.valueOf(in));p.setDate(2,Date.valueOf(out));p.setInt(3,id);return p.executeUpdate()>0;}}
    public boolean cancelReservation(int id)throws SQLException{return updateStatus(id,"CANCELLED","BOOKED");}
    public boolean checkIn(int id)throws SQLException{return updateStatus(id,"CHECKED_IN","BOOKED");}
    public boolean checkOut(int id)throws SQLException{return updateStatus(id,"CHECKED_OUT","CHECKED_IN");}
    private boolean updateStatus(int id,String to,String from)throws SQLException{String s="UPDATE reservations SET status=? WHERE reservation_id=? AND status=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setString(1,to);p.setInt(2,id);p.setString(3,from);return p.executeUpdate()>0;}}
    public double generateBill(int id)throws SQLException{String s="SELECT DATEDIFF(r.check_out,r.check_in) nights,rm.price_per_night FROM reservations r JOIN rooms rm ON r.room_id=rm.room_id WHERE r.reservation_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(r.next()){double charge=r.getInt(1)*r.getDouble(2);return charge+charge*.12;}}}return 0;}
    public boolean savePayment(int id,double amount,Connection c)throws SQLException{String s="INSERT INTO payments(reservation_id,amount,payment_status) VALUES(?,?,'PAID')";try(PreparedStatement p=c.prepareStatement(s)){p.setInt(1,id);p.setDouble(2,amount);return p.executeUpdate()>0;}}
    public void revenueReport()throws SQLException{String s="SELECT COUNT(*),COALESCE(SUM(amount),0) FROM payments WHERE payment_status='PAID'";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s);ResultSet r=p.executeQuery()){if(r.next())System.out.printf("Payments: %d | Revenue: ₹%.2f%n",r.getInt(1),r.getDouble(2));}}
}
